FUNCTION_SCHEMAS = {
    "get_order_status": {"order_id": "string"},
    "get_weather": {"city": "string"},
}

def get_order_status(order_id):
    orders = {"A100": "shipped"}
    if order_id not in orders:
        raise ValueError(f"Unknown order_id: {order_id}")
    return orders[order_id]

def get_weather(city):
    return f"Sunny in {city}"

def validate_call(name, arguments):
    # validate against the function's strict JSON schema
    schema = FUNCTION_SCHEMAS.get(name)
    if schema is None:
        return False, f"Unknown function: {name}"
    if set(arguments.keys()) != set(schema.keys()):
        return False, "Arguments do not match schema"
    return True, None

def execute_function_call(name, arguments):
    # feed errors back to the model instead of crashing
    valid, error = validate_call(name, arguments)
    if not valid:
        return {"error": error}
    try:
        functions = {"get_order_status": get_order_status, "get_weather": get_weather}
        result = functions[name](**arguments)
        return {"result": result}
    except ValueError as e:
        return {"error": str(e)}

# independent calls can run in parallel
requested_calls = [
    {"name": "get_order_status", "arguments": {"order_id": "A100"}},
    {"name": "get_weather", "arguments": {"city": "Boston"}},
    {"name": "get_order_status", "arguments": {"order_id": "Z999"}},
]

print("Function calling results:")
for call in requested_calls:
    outcome = execute_function_call(call["name"], call["arguments"])
    print(f"  {call['name']}({call['arguments']}) -> {outcome}")
